{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For each furnace, is the method choice made once for the whole 12-hour window (so a furnace assigned to method 1 runs 2-hour batches and one assigned to method 2 runs 3-hour batches), or can a single furnace switch between the two methods during the window?"
  ],
  "rationale": "The response asks a single clarification question regarding whether the method assignment is static for the entire window or dynamic per furnace."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a furnace is assigned to a method, does it have to run at least one batch, or can a furnace be left idle (assigned to a method but producing nothing)?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding furnace utilization."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a furnace is left idle, does it still count as \"assigned\" to one of the two methods (i.e., every furnace must be labeled method 1 or method 2 even if it produces nothing), or is \"idle\" a third, separate status that is not tied to either method?"
  ],
  "rationale": "The response asks for a single policy decision regarding the status of idle furnaces, presenting two mutually exclusive options for one concept."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the 12-hour limit a per-furnace limit (each furnace can run at most 12 hours of batches) or a single shared limit (the total batch time across both furnaces combined must be at most 12 hours)?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive interpretations of the 12-hour limit."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the objective to minimize total fuel cost, where the fuel cost of a method is charged once per furnace that runs that method (regardless of how many batches that furnace runs), or is it charged per batch?"
  ],
  "rationale": "The response asks for a single policy choice regarding how fuel cost is calculated (per furnace vs. per batch), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a furnace runs multiple batches of its assigned method, is the total time it consumes equal to (number of batches) × (time per batch for that method), with no setup or idle time between batches?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of a specific time calculation formula and the absence of setup/idle time."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the number of batches each furnace runs required to be whole numbers (you can't run half a batch), or can they be fractional?"
  ],
  "rationale": "The response asks a single clarification question regarding the integrality constraint for batch counts."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the minimum production requirement \"at least 30 tons\" (so producing 40 tons is acceptable), or must the total production be exactly 30 tons?"
  ],
  "rationale": "The response asks a single clarification question regarding the nature of the production constraint (minimum vs. exact), presenting two mutually exclusive options for the user to choose from."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a furnace is assigned to a method and runs at least one batch, is the fuel cost for that method charged even if the furnace's batches are not needed to reach the 30-ton minimum (i.e., cost is charged for any furnace that runs, not just those strictly needed)?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy decision regarding cost allocation, with no other independent requests."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can both furnaces be assigned to the same method (e.g., both run method 1), or must the two furnaces use different methods?"
  ],
  "rationale": "The response asks a single clarification question regarding the assignment constraints for the furnaces."
}

{
  "action": "question",
  "question_count": 1,
